import iconFacebook from '../assets/icon-facebook.svg'
import iconGoogle from '../assets/icon-google.svg'
import iconYelp from '../assets/icon-yelp.svg'

export type TestCasePriority = 'High' | 'Medium' | 'Low'

export interface ReviewResponseTestCase {
  id: number
  category: string
  scenario: string
  sampleInput: string
  expectedBehavior: string
  /** Star rating on the simulated review — `null` for the cases that specifically test a
   *  missing/absent rating. */
  rating: number | null
  /** The actual review text a customer wrote — `null` for the no-text cases where that's the
   *  point of the test. This is what renders in the preview card, not a summary of it. */
  reviewText: string | null
  /** The reply text the agent actually posted for this run — `null` when the correct/actual
   *  behavior is to hold, escalate, or suppress (no public reply is ever sent for that case). */
  reply: string | null
  /** Whether this run's actual behavior (`reply` above) matched `expectedBehavior`. */
  passed: boolean
  /** Set when `passed` is false — what went wrong, shown in the failed-case tile. */
  failureReason?: string
  priority: TestCasePriority
}

