export const REVIEW_RESPONSE_TEST_CASE_TOTAL = REVIEW_RESPONSE_TEST_CASES.length

export interface TestCasePlatform {
  label: string
  logo?: string
}

const PLATFORM_LOGOS: Record<string, string> = {
  Google: iconGoogle,
  Yelp: iconYelp,
  Facebook: iconFacebook,
}

/** Derives which platform a test case's review arrives on, straight from `sampleInput` — falls
 *  back to "All platforms" for cases that don't call one out (the built agent watches all sources). */
export function getPlatform(tc: ReviewResponseTestCase): TestCasePlatform {
  const match = tc.sampleInput.match(/Platform:\s*([A-Za-z-]+)/)
  const raw = match?.[1]
  if (raw && PLATFORM_LOGOS[raw]) return { label: raw, logo: PLATFORM_LOGOS[raw] }
  if (raw === 'no-reply-supported') return { label: 'Platform without public replies' }
  return { label: 'All platforms' }
}

/** Scenario + sample input, as the brief the simulation hands to the agent. */
export function getUserInstructions(tc: ReviewResponseTestCase): string {
  return `${tc.scenario}. ${tc.sampleInput}.`
}

/** Splits the expected-behavior assertion into bullet points on its natural `;` clauses. */
export function getExpectedBehaviorBullets(tc: ReviewResponseTestCase): string[] {
  return tc.expectedBehavior
    .split(';')
    .map((s) => s.trim())
    .filter(Boolean)
}
